(()=>{const el=id=>document.getElementById(id),n=id=>Number(el(id).value)||0,f=(v,d=1)=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:d}).format(v);function render(){const years=window.resolveProjectionYears||3,ticks=[1,3,5].filter(y=>y<=years),v=n('calc-labs')*n('calc-hplc-count')*n('calc-flow')*60*n('calc-hours-day')*n('calc-days-week')*n('calc-weeks-year')/1000,fresh=v*n('calc-recovery')/100,waste=v*n('calc-waste-reduction')/100,h=n('prep-hours')*n('calc-labs')*n('calc-weeks-year'),free=h*n('prep-reduction')/100,money=x=>'€'+f(x,0),litres=x=>f(x)+' L · ≈ '+f(x/1000,2)+' t',carbon=x=>f(x,2)+' t CO₂e',hours=x=>f(x)+' person-hours';const datasets={cost:{a:fresh*n('calc-solvent-cost'),b:waste*n('calc-disposal-cost'),la:'Material purchasing avoided',lb:'Disposal cost avoided',fmt:money},waste:{a:waste,b:v-waste,la:'Waste prevented',lb:'Waste remaining',fmt:litres},carbon:{a:fresh*3.69/1000,b:waste*1.57/1000,la:'Manufacture / production',lb:'Disposal / treatment',fmt:carbon},people:{a:free,b:h-free,la:'People time released',lb:'Preparation time remaining',fmt:hours}};for(const[key,d]of Object.entries(datasets)){const total=d.a+d.b,chart=el('cumulative-'+key);if(key==='people'&&!n('prep-hours')){chart.innerHTML='<p class="people-empty">Enter preparation person-hours in Mobile Phase Preparation to see the people impact.</p>';chart.setAttribute('aria-label','Preparation hours not entered');el('breakdown-people').textContent='No people-time benefit assumed until hours are entered.';continue;}chart.innerHTML=ticks.map(y=>{const tip=y+' years: '+d.la+' '+d.fmt(d.a*y)+'; '+d.lb+' '+d.fmt(d.b*y);return '<div class="impact-line-row" tabindex="0" title="'+tip+'" aria-label="'+tip+'"><div class="impact-line-label"><span>'+y+(y===1?' year':' years')+'</span><strong>'+d.fmt((key==='people'?d.a:total)*y)+'</strong></div><div class="impact-line-track"><div class="impact-line-fill" style="width:'+(total?y/years*100:0)+'%"><i class="impact-part-a" style="flex:'+d.a+'"></i><i class="impact-part-b" style="flex:'+d.b+'"></i></div></div></div>';}).join('');chart.setAttribute('aria-label',ticks.map(y=>y+' years: '+d.la+' '+d.fmt(d.a*y)+'; '+d.lb+' '+d.fmt(d.b*y)).join('; '));el('breakdown-'+key).innerHTML='<p><span class="cum-key a"></span>'+d.la+' <strong>'+d.fmt(d.a*years)+'</strong></p><p><span class="cum-key b"></span>'+d.lb+' <strong>'+d.fmt(d.b*years)+'</strong></p>'+(key==='waste'?'<p>Whole baseline: <strong>'+litres(v*years)+'</strong></p>':key==='people'?'<p>Baseline preparation: '+hours(h*years)+'. '+((n('prep-rate')/Number(document.getElementById('prep-paid-hours').value))?'Capacity value released: '+money(free*years*(n('prep-rate')/Number(document.getElementById('prep-paid-hours').value)))+'.':'Enter annual salary to value released time.')+'</p>':'');}el('projection-period-note').textContent='Cumulative totals over '+years+(years===1?' year':' years')+' · constant annual workload';}document.addEventListener('resolve-model',render);['prep-hours','prep-rate','prep-reduction'].forEach(id=>el(id).addEventListener('input',render));el('calc-reset').addEventListener('click',render);render();})();